class Sortable{static DragStart(t){t.dataTransfer.effectAllowed="move",t.dataTransfer.setData("text/plain",t.target.id),t.target.classList.add("dragging")}static DragOver(t){t.preventDefault(),t.dataTransfer.dropEffect="move";const e=t.target.closest("tr");e&&!e.classList.contains("dragging")&&e.classList.add("drag-over")}static DragLeave(t){const e=t.target.closest("tr");e&&e.classList.remove("drag-over")}static Drop(t){t.preventDefault();const e=t.dataTransfer.getData("text/plain"),a=document.getElementById(e),r=t.target.closest("tr");if(a&&r&&a!==r){r.classList.remove("drag-over");const t=r.parentNode,e=Array.from(t.children);e.indexOf(r)>e.indexOf(a)?r.after(a):r.before(a)}a.classList.remove("dragging")}static MakeSortable(t){const e=document.getElementsByClassName(t);for(const t of e)t.setAttribute("draggable","true"),t.addEventListener("dragstart",this.DragStart),t.addEventListener("dragover",this.DragOver),t.addEventListener("dragleave",this.DragLeave),t.addEventListener("drop",this.Drop)}}